import app from 'flarum/forum/app';
import usernameHelper from 'flarum/common/helpers/username';
import Avatar from 'flarum/common/components/Avatar';
import highlight from 'flarum/common/helpers/highlight';
import MentionableModel from './MentionableModel';
import getCleanDisplayName from '../utils/getCleanDisplayName';
export default class UserMention extends MentionableModel {
  type() {
    return 'user';
  }
  initialResults() {
    return Array.from(app.store.all('users'));
  }

  /**
   * Uses the user ID so autocomplete works regardless of the username's characters.
   */
  replacement(user) {
    const cleanText = getCleanDisplayName(user);
    return this.format.format(cleanText, '', user.id());
  }
  suggestion(model, typed) {
    const username = usernameHelper(model, name => highlight(name, typed));
    return m('[', null, m(Avatar, {
      user: model
    }), username);
  }
  matches(model, typed) {
    if (!typed) return false;
    const names = [model.username(), model.displayName()];
    return names.some(name => name.toLowerCase().substr(0, typed.length) === typed);
  }
  maxStoreMatchedResults() {
    return null;
  }
  async search(typed) {
    return await app.store.find('users', {
      filter: {
        q: typed
      },
      page: {
        limit: 5
      }
    });
  }
  enabled() {
    return true;
  }
}
flarum.reg.add('flarum-mentions', 'forum/mentionables/UserMention', UserMention);